import Foundation

/// Two short MP3 files (22.05 kHz mono sine tones, 3 s and 2 s), for tests that need real audio.
enum AudioFixtures {
    static let threeSecondMP3 = Data(base64Encoded: "")!
    static let twoSecondMP3 = Data(base64Encoded: "")!
}

/// Finds the repository's ffmpeg build (Tools/FFmpeg/build.sh) when none sits next to the test binary, so
/// the merge tests run from a plain `swift test`; they skip when there is none at all.
enum TestFFmpeg {
    static func prepare(file: String = #filePath) {
        guard ProcessInfo.processInfo.environment["IPODPROMAX_FFMPEG"] == nil else { return }
        let root = URL(fileURLWithPath: file).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        #if os(macOS)
        let folders = ["macos-arm64", "macos-x64", "macos-universal"]
        #elseif os(Linux)
        let folders = ["linux-arm64", "linux-x64"]
        #else
        let folders = ["windows-arm64", "windows-x64"]
        #endif
        for folder in folders {
            for name in ["ffmpeg", "ffmpeg.exe"] {
                let path = root.appendingPathComponent(".build-work/FFmpeg/\(folder)/\(name)").path
                if FileManager.default.isExecutableFile(atPath: path) { setenv("IPODPROMAX_FFMPEG", path, 1); return }
            }
        }
    }
}
